import { Injectable } from '@angular/core';
import { CaseUserInfoReq, TimeZoneRes, assignedUsersResponce, assignteamReq, assignteamRes, roleComboResponce, teamBuilderReq, teamBuilderRes, teamComboResponce, teamDeleteReq, teamDeleteRes, teamListResponce, userListReq, userListResponce } from '../../interfaces/teamsetup.interface';
import { SecureStorageService } from '../../../core/services/storage/secure-storage.service';
import { HttpClient, HttpHeaders, HttpParams } from '@angular/common/http';
import { TostbarService } from '../../../core/services/tost/tostbar.service';
import { firstValueFrom } from 'rxjs';
import { environment } from '../../../../environments/environment';

@Injectable({ providedIn: 'root' })
export class TeamsetupService {
  constructor(public sStore: SecureStorageService, private http: HttpClient, public tost: TostbarService) { }


  async teamList(nCaseid: string): Promise<teamListResponce[]> {
    try {
      const params = new HttpParams().set('nCaseid', nCaseid);
      const res: any = await firstValueFrom(
        this.http.get<teamListResponce[]>(`${environment.cloudUrl}${environment.coreservice}/team-data/teamlist`, { params: params })
      );

      return res;
    } catch (err) {
      return [];
    }
  }


  async teamColor(nCaseid: string): Promise<teamListResponce[]> {
    try {
      const params = new HttpParams().set('nCaseid', nCaseid);
      const res: any = await firstValueFrom(
        this.http.get<teamListResponce[]>(`${environment.cloudUrl}${environment.coreservice}/team-data/teamcolor`, {
          params: params
        })
      );
      return res;
    } catch (err) {
      return [];
    }
  }

  async assignedUsers(nCaseid: string): Promise<assignedUsersResponce[]> {
    try {
      const params = new HttpParams().set('nCaseid', nCaseid);
      const res: any = await firstValueFrom(
        this.http.get<assignedUsersResponce[]>(
          `${environment.cloudUrl}${environment.coreservice}/team-data/assignedusers`,
          { params: params }
        )
      );

      return res;
    } catch (err) {
      return [];
    }
  }




  async userList(mdl: userListReq): Promise<userListResponce[]> {
    try {
      var params = new HttpParams()
      for (const key in mdl) {
        if (mdl.hasOwnProperty(key)) {
          params = params.set(key, mdl[key]);
        }
      }
      const res: any = await firstValueFrom(
        this.http.get<userListResponce[]>(
          `${environment.cloudUrl}${environment.coreservice}/team-data/userlist`,
          { params: params }
        )
      );

      return res;
    } catch (err) {
      return [];
    }
  }


  async teamBuilder(mdl: teamBuilderReq): Promise<boolean> {
    try {
      const res: any = await firstValueFrom(
        this.http.post<teamBuilderRes>(`${environment.cloudUrl}${environment.coreservice}/team-setup/teambuilder`, mdl)
      );
      if (res && res.msg == 1) {
        this.tost.openSnackBar(res.value, '');
        return true;
      } else {
        this.tost.openSnackBar(res.value, 'E');
        return false;
      }
    } catch (err) {
      this.tost.openSnackBar(`team creation failed ${err}`, '');
      return false;
    }
  }



  async teamDelete(mdl: teamDeleteReq): Promise<boolean> {
    try {
      const res: any = await firstValueFrom(
        this.http.post<teamDeleteRes>(`${environment.cloudUrl}${environment.coreservice}/team-setup/teamdelete`, mdl)
      );
      if (res && res.msg == 1) {
        this.tost.openSnackBar(res.value, '');
        return true;
      } else {
        this.tost.openSnackBar(res.value, 'E');
        return false;
      }
    } catch (err) {
      this.tost.openSnackBar(`team deletion failed ${err}`, 'E');
      return false;
    }
  }



  async timezoneCombo(): Promise<TimeZoneRes[]> {
    try {
      const res: any = await firstValueFrom(
        this.http.get<TimeZoneRes[]>(
          `${environment.cloudUrl}${environment.coreservice}/team-data/timezone`
        )
      );

      return res;
    } catch (err) {
      return [];
    }
  }


  async assignTeam(mdl: assignteamReq): Promise<boolean> {
    try {
      const res: any = await firstValueFrom(
        this.http.post<assignteamRes>(`${environment.cloudUrl}${environment.coreservice}/team-setup/assignteam`, mdl)
      );
      if (res && res.msg == 1) {
        this.tost.openSnackBar(res.value, '');
        return true;
      } else {
        this.tost.openSnackBar(res.value, 'E');
        return false;
      }
    } catch (err) {
      this.tost.openSnackBar(`Team setup failed ${err}`, 'E');
      return false;
    }
  }



}
